package com.hotelmanagement.hms.purchase.web; import com.hotelmanagement.hms.purchase.dto.*; import com.hotelmanagement.hms.purchase.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.util.*; @RestController @RequestMapping("/api/v1/hotels/{hotel}/branches/{branch}/purchase-orders") public class PurchaseOrderController{private final PurchaseOrderService s;public PurchaseOrderController(PurchaseOrderService s){this.s=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED)public PurchaseOrderResponse create(@PathVariable UUID hotel,@PathVariable UUID branch,@Valid @RequestBody PurchaseOrderRequest q){return s.create(hotel,branch,q);}@PostMapping("/{id}/approve")public PurchaseOrderResponse approve(@PathVariable UUID hotel,@PathVariable UUID branch,@PathVariable UUID id){return s.approve(hotel,branch,id);}@PostMapping("/{id}/receive")@ResponseStatus(HttpStatus.NO_CONTENT)public void receive(@PathVariable UUID hotel,@PathVariable UUID branch,@PathVariable UUID id){s.receive(hotel,branch,id);}}
